const CARD_W = 160;
const CARD_H = 200;
const PAD_X = 32;
const PAD_Y = 32;

function scatterPositions(items) {
  const cols = 4;
  const cellW = CARD_W + PAD_X;
  const cellH = CARD_H + PAD_Y;
  const rows = Math.ceil(items.length / cols);
  const totalW = cols * cellW;
  const totalH = rows * cellH;
  const offsetX = -totalW / 2;
  const offsetY = -totalH / 2;
  return items.map((_, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const baseX = offsetX + col * cellW;
    const baseY = offsetY + row * cellH;
    const jitterX = (Math.random() - 0.5) * (PAD_X * 0.8);
    const jitterY = (Math.random() - 0.5) * (PAD_Y * 0.8);
    return { x: baseX + jitterX, y: baseY + jitterY };
  });
}

function gridPositions(items) {
  const cols = 2;
  const gapX = 24;
  const gapY = 24;
  const startX = -((cols * CARD_W + (cols - 1) * gapX) / 2) + CARD_W / 2;
  const startY = -Math.floor(items.length / cols) * ((CARD_H + gapY) / 2);
  return items.map((_, i) => ({
    x: startX + (i % cols) * (CARD_W + gapX),
    y: startY + Math.floor(i / cols) * (CARD_H + gapY),
  }));
}

const ItemCard = ({ item, style, onClick, isAdmin, onMarkSold, onPriceEdit }) => {
  const isClaimed = item.status === "claimed";
  const [editingPrice, setEditingPrice] = useState(false);
  const [priceInput, setPriceInput] = useState(String(item.price));

  const handlePriceSave = () => {
    const val = parseInt(priceInput, 10);
    if (!isNaN(val) && val > 0) onPriceEdit(item.id, val);
    setEditingPrice(false);
  };

  return (
    <div
      onClick={() => { if (!isAdmin && !isClaimed) onClick(item); }}
      style={{
        position: "absolute", width: CARD_W, height: CARD_H,
        background: "#fff",
        border: isAdmin ? "1.5px solid #000" : "1px solid #e0e0e0",
        borderRadius: 12, overflow: "hidden",
        cursor: isAdmin ? "default" : "pointer",
        display: "flex", flexDirection: "column", userSelect: "none",
        opacity: isAdmin && isClaimed ? 0.45 : 1,
        ...style,
      }}
    >
      <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
        <img src={item.images[0]} alt={item.name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block", pointerEvents: "none" }} />
        {item.images.length > 1 && (
          <div style={{ position: "absolute", bottom: 6, right: 6, background: "rgba(0,0,0,0.5)", color: "#fff", fontSize: 9, padding: "2px 5px", borderRadius: 8, fontFamily: "inherit" }}>
            1/{item.images.length}
          </div>
        )}
        {isAdmin && isClaimed && (
          <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
            <span style={{ fontFamily: "inherit", fontSize: 11, fontWeight: 600, color: "#fff", letterSpacing: "0.15em", transform: "rotate(-15deg)", border: "1.5px solid rgba(255,255,255,0.6)", padding: "2px 8px", borderRadius: 3, background: "rgba(0,0,0,0.45)" }}>SOLD</span>
          </div>
        )}
        {isAdmin && !isClaimed && (
          <div style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.52)", display: "flex", alignItems: "center", justifyContent: "center" }}>
            <button
              onClick={(e) => { e.stopPropagation(); onMarkSold(item.id); }}
              style={{ padding: "7px 14px", background: "#fff", color: "#000", border: "none", borderRadius: 8, fontSize: 11, fontWeight: 700, fontFamily: "inherit", cursor: "pointer", letterSpacing: "0.02em" }}
            >Mark Sold</button>
          </div>
        )}
      </div>
      <div style={{ padding: "8px 10px 10px", background: "#fff" }}>
        <div style={{ fontSize: 11, fontWeight: 600, color: "#000", marginBottom: 4, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", letterSpacing: "-0.01em" }}>{item.name}</div>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          {isAdmin && !isClaimed ? (
            editingPrice ? (
              <div style={{ display: "flex", gap: 3, alignItems: "center" }} onClick={e => e.stopPropagation()}>
                <span style={{ fontSize: 12, fontWeight: 700 }}>$</span>
                <input autoFocus value={priceInput} onChange={e => setPriceInput(e.target.value)} onBlur={handlePriceSave} onKeyDown={e => e.key === "Enter" && handlePriceSave()} style={{ width: 44, fontSize: 12, fontWeight: 700, border: "none", borderBottom: "1.5px solid #000", outline: "none", fontFamily: "inherit", background: "transparent" }} />
              </div>
            ) : (
              <span onClick={(e) => { e.stopPropagation(); setEditingPrice(true); setPriceInput(String(item.price)); }} style={{ fontSize: 13, fontWeight: 700, color: "#000", fontVariantNumeric: "tabular-nums", cursor: "text", borderBottom: "1px dashed #999", paddingBottom: 1 }}>${item.price}</span>
            )
          ) : (
            <span style={{ fontSize: 13, fontWeight: 700, color: "#000", fontVariantNumeric: "tabular-nums" }}>${item.price}</span>
          )}
          {isAdmin && isClaimed && <span style={{ fontSize: 10, color: "#aaa", fontWeight: 500 }}>Sold</span>}
        </div>
      </div>
    </div>
  );
};

const DetailSheet = ({ item, onClose, onClaim }) => {
  const [name, setName] = useState("");
  const [claimed, setClaimed] = useState(false);
  const [position, setPosition] = useState(null);
  const [photoIdx, setPhotoIdx] = useState(0);

  const handleClaim = () => {
    if (!name.trim()) return;
    const pos = item.status === "available" ? 1 : item.queue + 1;
    setPosition(pos);
    setClaimed(true);
    onClaim(item.id);
  };

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 100, display: "flex", flexDirection: "column", justifyContent: "flex-end" }}>
      <div onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.45)", backdropFilter: "blur(4px)" }} />
      <div style={{ position: "relative", background: "#fff", borderRadius: "20px 20px 0 0", padding: "0 0 40px", maxHeight: "88vh", overflowY: "auto", animation: "slideUp 0.3s cubic-bezier(0.32,0.72,0,1)" }}>
        <div style={{ width: 36, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "16px auto 0" }} />
        <div style={{ position: "relative", width: "100%", height: 260, overflow: "hidden", marginTop: 16 }}>
          <img src={item.images[photoIdx]} alt={item.name} style={{ width: "100%", height: "100%", objectFit: "cover", display: "block" }} />
          {item.images.length > 1 && (
            <>
              <div style={{ position: "absolute", bottom: 12, left: "50%", transform: "translateX(-50%)", display: "flex", gap: 5 }}>
                {item.images.map((_, i) => (
                  <div key={i} onClick={() => setPhotoIdx(i)} style={{ width: i === photoIdx ? 16 : 6, height: 6, borderRadius: 3, background: i === photoIdx ? "#fff" : "rgba(255,255,255,0.5)", cursor: "pointer", transition: "width 0.2s ease" }} />
                ))}
              </div>
              {photoIdx > 0 && <button onClick={() => setPhotoIdx(p => p - 1)} style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", background: "rgba(255,255,255,0.9)", border: "none", borderRadius: "50%", width: 32, height: 32, cursor: "pointer", fontSize: 14, fontFamily: "inherit" }}>‹</button>}
              {photoIdx < item.images.length - 1 && <button onClick={() => setPhotoIdx(p => p + 1)} style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", background: "rgba(255,255,255,0.9)", border: "none", borderRadius: "50%", width: 32, height: 32, cursor: "pointer", fontSize: 14, fontFamily: "inherit" }}>›</button>}
            </>
          )}
        </div>
        <div style={{ padding: "20px 24px 0" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 6 }}>
            <div style={{ flex: 1, marginRight: 12 }}>
              <div style={{ fontSize: 20, fontWeight: 700, letterSpacing: "-0.03em", color: "#000", lineHeight: 1.2 }}>{item.name}</div>
              <div style={{ fontSize: 11, color: "#999", marginTop: 3 }}>{item.category}</div>
            </div>
            <div style={{ fontSize: 24, fontWeight: 700, letterSpacing: "-0.03em", whiteSpace: "nowrap" }}>${item.price}</div>
          </div>
          <p style={{ fontSize: 13, color: "#555", lineHeight: 1.6, marginBottom: 20 }}>{item.description}</p>
          {!claimed ? (
            <>
              <div style={{ fontSize: 11, color: "#999", marginBottom: 8, letterSpacing: "0.05em", textTransform: "uppercase" }}>
                {item.status === "waitlist" ? `Join waitlist · ${item.queue} ahead` : "Claim this item"}
              </div>
              <div style={{ display: "flex", gap: 8 }}>
                <input value={name} onChange={e => setName(e.target.value)} placeholder="Your name" style={{ flex: 1, padding: "12px 14px", border: "1.5px solid #e0e0e0", borderRadius: 10, fontSize: 14, fontFamily: "inherit", outline: "none", color: "#000", background: "#fff" }} />
                <button onClick={handleClaim} style={{ padding: "12px 20px", background: name.trim() ? "#000" : "#e0e0e0", color: name.trim() ? "#fff" : "#999", border: "none", borderRadius: 10, fontSize: 14, fontWeight: 600, fontFamily: "inherit", cursor: name.trim() ? "pointer" : "default", transition: "all 0.15s ease", whiteSpace: "nowrap" }}>
                  {item.status === "waitlist" ? "Join queue" : "Claim it"}
                </button>
              </div>
            </>
          ) : (
            <div style={{ padding: 16, background: "#f5f5f5", borderRadius: 12, textAlign: "center" }}>
              <div style={{ fontSize: 22, marginBottom: 6 }}>✓</div>
              <div style={{ fontSize: 14, fontWeight: 600, color: "#000" }}>{position === 1 ? "You got it!" : `You're #${position} in line`}</div>
              <div style={{ fontSize: 12, color: "#999", marginTop: 4 }}>{position === 1 ? "I'll reach out to arrange pickup." : "I'll DM you if it opens up."}</div>
            </div>
          )}
        </div>
      </div>
      <style>{`@keyframes slideUp { from { transform: translateY(100%) } to { transform: translateY(0) } }`}</style>
    </div>
  );
};

const PasswordModal = ({ onSuccess, onDismiss }) => {
  const [pw, setPw] = useState("");
  const [error, setError] = useState(false);
  const attempt = () => {
    if (pw === "lydia") { onSuccess(); }
    else { setError(true); setPw(""); setTimeout(() => setError(false), 1200); }
  };
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 200, display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div onClick={onDismiss} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.4)", backdropFilter: "blur(6px)" }} />
      <div style={{ position: "relative", background: "#fff", borderRadius: 16, padding: "28px 24px", width: 280, animation: "slideUp 0.2s ease" }}>
        <div style={{ fontSize: 14, fontWeight: 700, letterSpacing: "-0.02em", marginBottom: 4 }}>Admin mode</div>
        <div style={{ fontSize: 12, color: "#999", marginBottom: 18 }}>Enter password to continue</div>
        <input autoFocus type="password" value={pw} onChange={e => setPw(e.target.value)} onKeyDown={e => e.key === "Enter" && attempt()} placeholder="Password" style={{ width: "100%", padding: "11px 14px", border: `1.5px solid ${error ? "#ff4444" : "#e0e0e0"}`, borderRadius: 10, fontSize: 14, fontFamily: "inherit", outline: "none", color: "#000", background: error ? "#fff5f5" : "#fff", transition: "all 0.15s ease", marginBottom: error ? 6 : 10 }} />
        {error && <div style={{ fontSize: 11, color: "#ff4444", marginBottom: 10 }}>Incorrect password</div>}
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={onDismiss} style={{ flex: 1, padding: "11px", background: "#f5f5f5", color: "#000", border: "none", borderRadius: 10, fontSize: 13, fontWeight: 600, fontFamily: "inherit", cursor: "pointer" }}>Cancel</button>
          <button onClick={attempt} style={{ flex: 1, padding: "11px", background: "#000", color: "#fff", border: "none", borderRadius: 10, fontSize: 13, fontWeight: 600, fontFamily: "inherit", cursor: "pointer" }}>Unlock</button>
        </div>
      </div>
    </div>
  );
};

const AddItemSheet = ({ onClose, onAdd }) => {
  const [images, setImages] = useState([]);
  const [loading, setLoading] = useState(false);
  const [fields, setFields] = useState(null);
  const [error, setError] = useState(null);
  const fileRef = useRef(null);

  const toBase64 = (file) => new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = () => res(r.result);
    r.onerror = rej;
    r.readAsDataURL(file);
  });

  const handleFiles = async (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;
    const b64s = await Promise.all(files.map(toBase64));
    setImages(b64s);
    setLoading(true);
    setError(null);
    setFields(null);

    try {
      const content = [
        { type: "text", text: "You are a moving sale listing assistant. Look at the photo(s) and return ONLY valid JSON with these fields: name (short product name), price (integer CAD, fair used price), category (one of: Clothing, Furniture, Kitchen, Tech, Wellness, Fitness, Decor, Beauty, Utility), description (1-2 sentences, honest condition, key features). No markdown, no extra text." },
        ...b64s.map(b => ({ type: "image", source: { type: "base64", media_type: "image/jpeg", data: b.split(",")[1] } }))
      ];

      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 400,
          messages: [{ role: "user", content }]
        })
      });
      const data = await res.json();
      const text = data.content?.find(b => b.type === "text")?.text || "";
      const clean = text.replace(/```json|```/g, "").trim();
      const parsed = JSON.parse(clean);
      setFields({ name: parsed.name || "", price: parsed.price || 20, category: parsed.category || "Utility", description: parsed.description || "" });
    } catch (e) {
      setError("Couldn't auto-fill. Fill in manually.");
      setFields({ name: "", price: 20, category: "Utility", description: "" });
    }
    setLoading(false);
  };

  const handleSubmit = () => {
    if (!fields?.name.trim() || !images.length) return;
    onAdd({ name: fields.name, price: Number(fields.price), category: fields.category, description: fields.description, images, status: "available", queue: 0 });
    onClose();
  };

  const CATS = ["Clothing","Furniture","Kitchen","Tech","Wellness","Fitness","Decor","Beauty","Utility"];

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 100, display: "flex", flexDirection: "column", justifyContent: "flex-end" }}>
      <div onClick={onClose} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.45)", backdropFilter: "blur(4px)" }} />
      <div style={{ position: "relative", background: "#fff", borderRadius: "20px 20px 0 0", padding: "0 0 40px", maxHeight: "92vh", overflowY: "auto", animation: "slideUp 0.3s cubic-bezier(0.32,0.72,0,1)" }}>
        <div style={{ width: 36, height: 4, background: "#e0e0e0", borderRadius: 2, margin: "16px auto 12px" }} />
        <div style={{ padding: "0 24px" }}>
          <div style={{ fontSize: 16, fontWeight: 700, letterSpacing: "-0.03em", marginBottom: 20 }}>Add Item</div>

          {/* Photo upload */}
          <input ref={fileRef} type="file" accept="image/*" multiple onChange={handleFiles} style={{ display: "none" }} />
          {images.length === 0 ? (
            <div onClick={() => fileRef.current?.click()} style={{ width: "100%", height: 180, border: "1.5px dashed #ccc", borderRadius: 12, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", cursor: "pointer", gap: 8, marginBottom: 20, background: "#fafafa" }}>
              <div style={{ fontSize: 28 }}>+</div>
              <div style={{ fontSize: 13, color: "#999" }}>Tap to add photos</div>
              <div style={{ fontSize: 11, color: "#bbb" }}>Multiple photos supported</div>
            </div>
          ) : (
            <div style={{ display: "flex", gap: 8, marginBottom: 20, overflowX: "auto", paddingBottom: 4 }}>
              {images.map((src, i) => (
                <img key={i} src={src} alt="" style={{ width: 90, height: 90, objectFit: "cover", borderRadius: 8, flexShrink: 0, border: "1px solid #e0e0e0" }} />
              ))}
              <div onClick={() => fileRef.current?.click()} style={{ width: 90, height: 90, border: "1.5px dashed #ccc", borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", flexShrink: 0, fontSize: 22, color: "#bbb" }}>+</div>
            </div>
          )}

          {loading && (
            <div style={{ textAlign: "center", padding: "24px 0", color: "#999", fontSize: 13 }}>
              <div style={{ fontSize: 20, marginBottom: 8, animation: "spin 1s linear infinite", display: "inline-block" }}>◌</div>
              <div>Auto-filling from photo…</div>
            </div>
          )}

          {error && <div style={{ fontSize: 12, color: "#999", marginBottom: 12 }}>{error}</div>}

          {fields && !loading && (
            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
              <div>
                <div style={{ fontSize: 11, color: "#999", marginBottom: 5, letterSpacing: "0.04em", textTransform: "uppercase" }}>Name</div>
                <input value={fields.name} onChange={e => setFields(f => ({...f, name: e.target.value}))} style={{ width: "100%", padding: "11px 14px", border: "1.5px solid #e0e0e0", borderRadius: 10, fontSize: 14, fontFamily: "inherit", outline: "none", color: "#000" }} />
              </div>
              <div style={{ display: "flex", gap: 12 }}>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 11, color: "#999", marginBottom: 5, letterSpacing: "0.04em", textTransform: "uppercase" }}>Price ($)</div>
                  <input type="number" value={fields.price} onChange={e => setFields(f => ({...f, price: e.target.value}))} style={{ width: "100%", padding: "11px 14px", border: "1.5px solid #e0e0e0", borderRadius: 10, fontSize: 14, fontFamily: "inherit", outline: "none", color: "#000" }} />
                </div>
                <div style={{ flex: 1 }}>
                  <div style={{ fontSize: 11, color: "#999", marginBottom: 5, letterSpacing: "0.04em", textTransform: "uppercase" }}>Category</div>
                  <select value={fields.category} onChange={e => setFields(f => ({...f, category: e.target.value}))} style={{ width: "100%", padding: "11px 14px", border: "1.5px solid #e0e0e0", borderRadius: 10, fontSize: 13, fontFamily: "inherit", outline: "none", color: "#000", background: "#fff", appearance: "none" }}>
                    {CATS.map(c => <option key={c}>{c}</option>)}
                  </select>
                </div>
              </div>
              <div>
                <div style={{ fontSize: 11, color: "#999", marginBottom: 5, letterSpacing: "0.04em", textTransform: "uppercase" }}>Description</div>
                <textarea value={fields.description} onChange={e => setFields(f => ({...f, description: e.target.value}))} rows={3} style={{ width: "100%", padding: "11px 14px", border: "1.5px solid #e0e0e0", borderRadius: 10, fontSize: 13, fontFamily: "inherit", outline: "none", color: "#000", resize: "none", lineHeight: 1.5 }} />
              </div>
              <button onClick={handleSubmit} style={{ width: "100%", padding: "14px", background: fields.name.trim() ? "#000" : "#e0e0e0", color: fields.name.trim() ? "#fff" : "#999", border: "none", borderRadius: 12, fontSize: 15, fontWeight: 700, fontFamily: "inherit", cursor: fields.name.trim() ? "pointer" : "default", marginTop: 4 }}>
                Add to Sale
              </button>
            </div>
          )}
        </div>
      </div>
      <style>{`
        @keyframes spin { from { transform: rotate(0deg) } to { transform: rotate(360deg) } }
      `}</style>
    </div>
  );
};

export default function App() {
  const [isGrid, setIsGrid] = useState(false);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showPasswordModal, setShowPasswordModal] = useState(false);
  const [showAddSheet, setShowAddSheet] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [items, setItems] = useState(ITEMS);
  const [transform, setTransform] = useState({ x: 0, y: 0, scale: 1 });
  const [animating, setAnimating] = useState(false);

  // visible items depends on admin mode
  const visibleItems = isAdmin ? items : items.filter(i => i.status !== "claimed");
  const [positions, setPositions] = useState(() => scatterPositions(visibleItems));

  const canvasRef = useRef(null);
  const isDragging = useRef(false);
  const lastPointer = useRef({ x: 0, y: 0 });
  const lastPinchDist = useRef(null);
  const dragMoved = useRef(false);
  const longPressTimer = useRef(null);

  // Recalculate positions when visible items change
  useEffect(() => {
    setPositions(scatterPositions(visibleItems));
  }, [isAdmin]);

  const availableCount = items.filter(i => i.status === "available").length;

  const handleTitlePressStart = () => {
    longPressTimer.current = setTimeout(() => {
      if (isAdmin) setIsAdmin(false);
      else setShowPasswordModal(true);
    }, 600);
  };
  const handleTitlePressEnd = () => clearTimeout(longPressTimer.current);

  const toggleMode = () => {
    const next = !isGrid;
    setIsGrid(next);
    setAnimating(true);
    const newPos = next ? gridPositions(visibleItems) : scatterPositions(visibleItems);
    if (next) setTransform({ x: 0, y: 0, scale: 1 });
    let start = null;
    const duration = 600;
    const fromPos = [...positions];
    const animate = (ts) => {
      if (!start) start = ts;
      const t = Math.min((ts - start) / duration, 1);
      const ease = t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
      setPositions(fromPos.map((p, i) => ({ x: p.x + ((newPos[i]?.x ?? p.x) - p.x) * ease, y: p.y + ((newPos[i]?.y ?? p.y) - p.y) * ease })));
      if (t < 1) requestAnimationFrame(animate);
      else { setPositions(newPos); setAnimating(false); }
    };
    requestAnimationFrame(animate);
  };

  const onPointerDown = useCallback((e) => {
    if (selectedItem) return;
    isDragging.current = true;
    dragMoved.current = false;
    lastPointer.current = { x: e.clientX, y: e.clientY };
  }, [selectedItem]);

  const onPointerMove = useCallback((e) => {
    if (!isDragging.current) return;
    const dx = e.clientX - lastPointer.current.x;
    const dy = e.clientY - lastPointer.current.y;
    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) dragMoved.current = true;
    lastPointer.current = { x: e.clientX, y: e.clientY };
    setTransform(t => ({ ...t, x: t.x + dx, y: t.y + dy }));
  }, []);

  const onPointerUp = useCallback(() => { isDragging.current = false; }, []);

  const onTouchStart = useCallback((e) => {
    if (e.touches.length === 2) {
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      lastPinchDist.current = Math.sqrt(dx * dx + dy * dy);
    }
  }, []);

  const onTouchMove = useCallback((e) => {
    if (e.touches.length === 2) {
      const dx = e.touches[0].clientX - e.touches[1].clientX;
      const dy = e.touches[0].clientY - e.touches[1].clientY;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (lastPinchDist.current) {
        const delta = dist / lastPinchDist.current;
        setTransform(t => ({ ...t, scale: Math.min(Math.max(t.scale * delta, 0.3), 3) }));
      }
      lastPinchDist.current = dist;
      e.preventDefault();
    }
  }, []);

  const onWheel = useCallback((e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? 0.9 : 1.1;
    setTransform(t => ({ ...t, scale: Math.min(Math.max(t.scale * delta, 0.3), 3) }));
  }, []);

  useEffect(() => {
    const el = canvasRef.current;
    if (!el) return;
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("touchmove", onTouchMove, { passive: false });
    return () => { el.removeEventListener("wheel", onWheel); el.removeEventListener("touchmove", onTouchMove); };
  }, [onWheel, onTouchMove]);

  const handleClaim = (id) => {
    setItems(prev => prev.map(item => {
      if (item.id !== id) return item;
      if (item.status === "available") return { ...item, status: "claimed" };
      return { ...item, queue: item.queue + 1 };
    }));
  };

  const handleMarkSold = (id) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, status: "claimed" } : item));
  };

  const handlePriceEdit = (id, newPrice) => {
    setItems(prev => prev.map(item => item.id === id ? { ...item, price: newPrice } : item));
  };

  const handleAddItem = (newItem) => {
    const id = Date.now();
    setItems(prev => {
      const updated = [...prev, { ...newItem, id }];
      setPositions(scatterPositions(isAdmin ? updated : updated.filter(i => i.status !== "claimed")));
      return updated;
    });
  };

  return (
    <div style={{ width: "100vw", height: "100vh", overflow: "hidden", background: "#fafafa", fontFamily: "'Geist', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', sans-serif", position: "relative" }}>
      {isAdmin && (
        <div style={{ position: "fixed", top: 0, left: 0, right: 0, zIndex: 60, background: "#000", color: "#fff", fontSize: 11, fontWeight: 600, letterSpacing: "0.08em", textAlign: "center", padding: "5px 0", textTransform: "uppercase" }}>
          Admin mode · hold title to exit
        </div>
      )}

      <div style={{ position: "fixed", top: isAdmin ? 28 : 0, left: 0, right: 0, zIndex: 50, padding: "16px 20px", display: "flex", alignItems: "center", justifyContent: "space-between", borderBottom: "1px solid #efefef", background: "rgba(250,250,250,0.92)", backdropFilter: "blur(12px)", transition: "top 0.2s ease" }}>
        <div onMouseDown={handleTitlePressStart} onMouseUp={handleTitlePressEnd} onMouseLeave={handleTitlePressEnd} onTouchStart={handleTitlePressStart} onTouchEnd={handleTitlePressEnd} style={{ cursor: "default", userSelect: "none" }}>
          <div style={{ fontSize: 15, fontWeight: 700, letterSpacing: "-0.03em", color: "#000" }}>Lydia's Moving Sale</div>
          <div style={{ fontSize: 11, color: "#999", marginTop: 1 }}>{availableCount} of {items.length} still available · Toronto → NYC</div>
        </div>
        <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
          {isAdmin && (
            <>
              <button onClick={() => setShowAddSheet(true)} style={{ padding: "8px 14px", background: "#000", color: "#fff", border: "none", borderRadius: 20, fontSize: 12, fontWeight: 700, fontFamily: "inherit", cursor: "pointer", letterSpacing: "0.01em" }}>+ Add</button>
              <button onClick={() => setIsAdmin(false)} style={{ padding: "8px 12px", background: "#fff", color: "#000", border: "1.5px solid #000", borderRadius: 20, fontSize: 11, fontWeight: 600, fontFamily: "inherit", cursor: "pointer" }}>Lock</button>
            </>
          )}
          <button onClick={toggleMode} disabled={animating} style={{ padding: "8px 14px", background: isGrid ? "#000" : "#fff", color: isGrid ? "#fff" : "#000", border: "1.5px solid #000", borderRadius: 20, fontSize: 12, fontWeight: 600, fontFamily: "inherit", cursor: animating ? "default" : "pointer", transition: "all 0.2s ease" }}>
            {isGrid ? "Canvas" : "Grid"}
          </button>
        </div>
      </div>

      <div ref={canvasRef} onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerUp} onPointerLeave={onPointerUp} onTouchStart={onTouchStart} style={{ width: "100%", height: "100%", cursor: "grab", touchAction: "none" }}>
        <div style={{ position: "absolute", top: "50%", left: "50%", transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})`, transformOrigin: "0 0", willChange: "transform" }}>
          {visibleItems.map((item, i) => (
            <ItemCard
              key={item.id}
              item={item}
              isAdmin={isAdmin}
              onMarkSold={handleMarkSold}
              onPriceEdit={handlePriceEdit}
              style={{ transform: `translate(${positions[i]?.x ?? 0}px, ${positions[i]?.y ?? 0}px)` }}
              onClick={(item) => { if (!dragMoved.current) setSelectedItem(item); }}
            />
          ))}
        </div>
      </div>

      {!isGrid && !isAdmin && (
        <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", fontSize: 11, color: "#bbb", letterSpacing: "0.05em", pointerEvents: "none", whiteSpace: "nowrap" }}>
          drag to explore · pinch to zoom
        </div>
      )}

      {selectedItem && !isAdmin && (
        <DetailSheet item={selectedItem} onClose={() => setSelectedItem(null)} onClaim={handleClaim} />
      )}

      {showPasswordModal && (
        <PasswordModal onSuccess={() => { setShowPasswordModal(false); setIsAdmin(true); }} onDismiss={() => setShowPasswordModal(false)} />
      )}

      {showAddSheet && (
        <AddItemSheet onClose={() => setShowAddSheet(false)} onAdd={handleAddItem} />
      )}

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Geist:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        input::placeholder, textarea::placeholder { color: #bbb; }
        input:focus, textarea:focus, select:focus { border-color: #000 !important; }
        @keyframes slideUp { from { transform: translateY(100%); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
      `}</style>
    </div>
  );
}
